/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode sortList(ListNode head) {
        return mergeSort(head);
    }

    ListNode mergeSort(ListNode start) {
        if (start == null || start.next == null) {
            return start;
        }

        ListNode slow = start, fast = start.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }


        var second = slow.next;
        slow.next = null; // 使前后两段链表断开

        var left = mergeSort(start);
        var right = mergeSort(second);
        return merge(left, right);
    }

    // 简单的合并两个排序好的链表即可 https://leetcode.com/problems/merge-two-sorted-lists/
    ListNode merge(ListNode left, ListNode right) {
        var dummy = new ListNode();
        var cur = dummy;
        while (left != null && right != null) {
            if (left.val <= right.val) {
                cur.next = left;
                left = left.next;
            } else {
                cur.next = right;
                right = right.next;
            }
            cur = cur.next;
        }

        if (left != null) {
            cur.next = left;
        }

        if (right != null) {
            cur.next = right;
        }

        return dummy.next;
    }
}

